#!/usr/bin/env bash
# Generate Python (pydantic v2) and TypeScript types from contracts/*.schema.json.
# Usage: scripts/codegen.sh          -> regenerate
#        scripts/codegen.sh --check  -> fail if generated files differ from committed ones
set -euo pipefail
cd "$(dirname "$0")/.."
OUT_PY=seen/contracts
OUT_TS=${WEB_DIR:-web}/src/contracts.ts   # WEB_DIR=../baywatch when the website is a separate checkout
TMP=$(mktemp -d)
trap 'rm -rf "$TMP"' EXIT

gen_py() {
  mkdir -p "$TMP/py"
  for s in events workorder metrics; do
    uvx --from 'datamodel-code-generator' datamodel-codegen \
      --input "contracts/$s.schema.json" --input-file-type jsonschema \
      --output "$TMP/py/$s.py" --output-model-type pydantic_v2.BaseModel \
      --use-standard-collections --use-union-operator --target-python-version 3.11 \
      --disable-timestamp --formatters black isort 2>/dev/null
    sed -i.bak '1s/^.*$/# GENERATED by scripts\/codegen.sh from contracts\/'"$s"'.schema.json. Do not edit./' "$TMP/py/$s.py" && rm "$TMP/py/$s.py.bak"
  done
  echo '"""GENERATED contract models (pydantic v2). Regenerate with scripts/codegen.sh."""' > "$TMP/py/__init__.py"
}

gen_ts() {
  mkdir -p "$TMP/ts"
  {
    echo '// GENERATED by scripts/codegen.sh from contracts/*.schema.json. Do not edit.'
    for s in events workorder metrics; do
      npx --yes json-schema-to-typescript@15 --no-additionalProperties --bannerComment '' \
        --unreachableDefinitions -i "contracts/$s.schema.json"
    done
  } > "$TMP/contracts.ts"
}

gen_py
gen_ts
if [ "${1:-}" = "--check" ]; then
  diff -rq "$TMP/py" "$OUT_PY" && diff -q "$TMP/contracts.ts" "$OUT_TS" && echo "contracts in sync"
else
  mkdir -p "$(dirname "$OUT_TS")"
  rm -rf "$OUT_PY" && cp -r "$TMP/py" "$OUT_PY"
  cp "$TMP/contracts.ts" "$OUT_TS"
  echo "generated $OUT_PY and $OUT_TS"
fi
